const body = $input.first().json.body;

// Extract base64 data
let base64Data = body.photo;
let fileName = body.fileName || `photo_${Date.now()}.jpg`;
let mimeType = 'image/jpeg';

// Handle data URL format (data:image/jpeg;base64,...)
if (base64Data.startsWith('data:')) {
  const matches = base64Data.match(/^data:([^;]+);base64,(.+)$/);
  if (matches) {
    mimeType = matches[1];
    base64Data = matches[2];

    // Set correct extension based on mime type
    const ext = mimeType.split('/')[1];
    if (!fileName.includes('.')) {
      fileName = `${fileName}.${ext}`;
    }
  }
}

// Return with binary data in 'data' field (required by Google Drive node)
return [{
  json: {
    fileName: fileName,
    mimeType: mimeType,
    itemId: body.itemId,
    itemName: body.itemName
  },
  binary: {
    data: {
      data: base64Data,
      mimeType: mimeType,
      fileName: fileName
    }
  }
}];

const driveFile = $('Upload to Drive').first().json;
const inputData = $('Prepare File').first().json;

// Create direct link to the image
const directUrl = `https://drive.google.com/uc?export=view&id=${driveFile.id}`;

return [{
  json: {
    success: true,
    data: {
      fileId: driveFile.id,
      fileName: driveFile.name,
      url: directUrl,
      itemId: inputData.itemId,
      itemName: inputData.itemName
    }
  }
}];
